use vstd::prelude::*;

verus! {

    // longest(strings) returns None exactly when strings.len()==0.
    // Otherwise it returns Some(seq) where
    //  • seq equals strings[idx] for some 0 ≤ idx < strings.len(),
    //  • for every j < strings.len(), strings[j].len() ≤ seq.len(),
    //  • and for every k < idx,       strings[k].len() <  seq.len().
    fn longest(strings: Vec<Vec<char>>) -> (result: Option<Vec<char>>)
        ensures
            match result {
                Option::None => strings.len() == 0,
                Option::Some(seq) => {
                    strings.len() > 0
                    &&
                    exists |idx: usize| 
                        idx < strings.len()
                        && seq == strings[idx]
                        // no one is longer than it
                        && (forall |j: usize| j < strings.len() ==> strings[j].len() <= seq.len())
                        // and any earlier index is strictly shorter
                        && (forall |k: usize| k < idx           ==> strings[k].len() <  seq.len())
                }
            }
    {
        // Handle the empty‐list case immediately
        if strings.len() == 0 {
            return Option::None;
        }

        let n = strings.len();

        // Initialize best to the 0th element
        let mut best_idx: usize    = 0;
        let mut best:     Vec<char> = strings[0].clone();
        let mut best_len: usize     = best.len();

        // Scan the remainder of the list
        let mut i: usize = 1;
        while i < n
            invariant
                // 1 ≤ i ≤ n
                1 <= i && i <= n,

                // best_idx is in [0, i)
                best_idx < i,

                // best and best_len are consistent
                best.len() == best_len,
                best == strings[best_idx],

                // among indices < i, best_len is maximal
                forall |j: usize|
                    j < i ==> strings[j].len() <= best_len,

                // and among indices < best_idx, lengths are strictly smaller
                forall |k: usize|
                    k < best_idx ==> strings[k].len() < best_len,

            decreases n - i
        {
            let curr_len = strings[i].len();
            if curr_len > best_len {
                best_len = curr_len;
                best_idx = i;
                best     = strings[i].clone();
            }
            i = i + 1;
        }

        // At this point i == n, and the invariants guarantee that
        // best is exactly the earliest longest sequence in [0..n).
        Option::Some(best)
    }

} // end verus!

